user?.address?.city ?? "Unknown";

// Logical assignment
config.timeout ??= 5000;

// Array/Object spread
const merged = { ...a, ...b };

// Top-level await
const config = await fetch("/config.json").then(r => r.json());

// Private class fields
class Counter { #count = 0; inc() { return ++this.#count; } }

// Numeric separators
const billion = 1_000_000_000;

// Array methods
arr.at(-1);
arr.flat(Infinity);
arr.findLast(x => x > 5);
arr.toSorted();

// Object.groupBy
Object.groupBy(items, i => i.category);

// String.replaceAll
"a-b-c".replaceAll("-", "_");
```

