fetch(`/api/products?${params}`);

// With timeout
async function fetchWithTimeout(url, ms = 5000) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), ms);
  try {
    const res = await fetch(url, { signal: controller.signal });
    return res.json();
  } finally {
    clearTimeout(timer);
  }
}

// File upload
const formData = new FormData();
formData.append("file", fileInput.files[0]);
formData.append("name", "resume.pdf");
await fetch("/api/upload", { method: "POST", body: formData });
// Note: do NOT set Content-Type — the browser sets the boundary
```

**Response handling**

```javascript
res.ok;          // true if status 200–299
res.status;      // 200
res.statusText;  // "OK"
res.headers.get("content-type");
await res.json();
await res.text();
await res.blob();
await res.formData();
```

### 13.9 Error Handling in Async Code

```javascript
// Global handlers
window.addEventListener("unhandledrejection", (e) => {
  console.error("Unhandled promise:", e.reason);
});
window.addEventListener("error", (e) => {
  console.error("Runtime error:", e.error);
});

// Retry with exponential backoff
async function retry(fn, attempts = 3, baseDelay = 300) {
  let lastError;
  for (let i = 0; i < attempts; i++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err;
      await new Promise(r => setTimeout(r, baseDelay * 2 ** i));
    }
  }
  throw lastError;
}
```

### 13.10 LocalStorage

```javascript
// Store
localStorage.setItem("theme", "dark");
localStorage.setItem("user", JSON.stringify({ id: 1, name: "Asha" }));

// Read
const theme = localStorage.getItem("theme");
const user = JSON.parse(localStorage.getItem("user") ?? "null");

// Remove
localStorage.removeItem("theme");
localStorage.clear();

// Storage wrapper with namespacing
const store = {
  prefix: "ethiroli:",
  set(key, value) {
    localStorage.setItem(this.prefix + key, JSON.stringify(value));
  },
  get(key, fallback = null) {
    try {
      const raw = localStorage.getItem(this.prefix + key);
      return raw ? JSON.parse(raw) : fallback;
    } catch {
      return fallback;
    }
  },
  remove(key) { localStorage.removeItem(this.prefix + key); },
  clear() {
    Object.keys(localStorage)
      .filter(k => k.startsWith(this.prefix))
      .forEach(k => localStorage.removeItem(k));
  },
};

store.set("user", { id: 1 });
store.get("user");   // { id: 1 }
```

| | `localStorage` | `sessionStorage` | Cookies |
|---|---|---|---|
| Persists after close | ✅ | ❌ | ✅ |
| Size limit | ~5 MB | ~5 MB | ~4 KB |
| Sent to server | ❌ | ❌ | ✅ |
| Accessible from JS | ✅ | ✅ | ✅ (non-HttpOnly) |

> ⚠️ Never store JWTs in `localStorage` in production — prefer HttpOnly cookies.

### 13.11 Modern JS Features

```javascript
// Optional chaining & nullish
user?.address?.city ?? "Unknown";

// Logical assignment
config.timeout ??= 5000;

// Array/Object spread
const merged = { ...a, ...b };

// Top-level await
const config = await fetch("/config.json").then(r => r.json());

// Private class fields
class Counter { #count = 0; inc() { return ++this.#count; } }

// Numeric separators
const billion = 1_000_000_000;

// Array methods
arr.at(-1);
arr.flat(Infinity);
arr.findLast(x => x > 5);
arr.toSorted();

// Object.groupBy
Object.groupBy(items, i => i.category);

// String.replaceAll
"a-b-c".replaceAll("-", "_");
```

