        value={query}
        onChange={e => {
          setQuery(e.target.value);
          startTransition(() => { /* mark follow-up updates as non-urgent */ });
        }}
      />
      {isPending && <Spinner />}
      <List items={filtered} />
    </>
  );
}
```

