}

function CourseGridSkeleton({ count = 6 }) {
  return (
    <div className="course-grid" role="status" aria-label="Loading courses">
      {Array.from({ length: count }, (_, i) => <CourseCardSkeleton key={i} />)}
      <span className="visually-hidden">Loading…</span>
    </div>
  );
}
```

